processes.script_excerpt:
def args = task.ext.args ?: ""

// | input     | output     | command1 | command2 |
// |-----------|------------|----------|----------|
// | gzipped   | gzipped    | cat      |          |
// | ungzipped | ungzipped  | cat      |          |
// | gzipped   | ungzipped  | pigz     |          |
// | ungzipped | gzipped    | cat      | pigz     |

// Use input file ending as default
// get file extensions, if extension is .gz then get the second to last extension as well
file_extensions = files_in.collect { in_file -> in_file.name - in_file.getBaseName(in_file.name.endsWith('.gz') ? 2 : 1) }

// Use input file ending as default for output file
prefix = task.ext.prefix ?: "${meta.id}${file_extensions[0]}"

if (files_in.any{ file -> file.toString().endsWith('.gz')} && !files_in.every{ file -> file.toString().endsWith('.gz') }) {
    error("All files provided to this module must either be gzipped (and have the .gz extension) or unzipped (and not have the .gz extension). A mix of both is not allowed.")
}

in_zip = files_in[0].toString().endsWith('.gz')
out_zip = task.ext.prefix ? task.ext.prefix.endsWith('.gz') : file_extensions[0].endsWith('.gz')

out_fname = in_zip && out_zip ? prefix : prefix.endsWith('.gz') ? prefix.replace('.gz', '') : prefix

cmd1 = in_zip && !out_zip ? "pigz -cd -p ${task.cpus}" : "cat"
cmd2 = !in_zip && out_zip ? "pigz -p ${task.cpus} ${args} ${out_fname}" : ""

"""
while IFS= read -r -d \$'\\0' file; do
        ${cmd1} \$file \\
            >> ${out_fname}
    done < <( find to_concatenate/ -mindepth 1 -print0 | sort -z )

${cmd2}

def args = task.ext.args ?: ''
def prefix = task.ext.prefix ?: "${meta.id}"
// Make list of old name and new name pairs to use for renaming in the bash while loop
def old_new_pairs = reads instanceof Path || reads.size() == 1 ? [[reads, "${prefix}.${reads.extension}"]] : reads.withIndex().collect { entry, index -> [entry, "${prefix}_${index + 1}.${entry.extension}"] }
def rename_to = old_new_pairs*.join(' ').join(' ')
def renamed_files = old_new_pairs.collect { _old_name, new_name -> new_name }.join(' ')

// The total amount of allocated RAM by FastQC is equal to the number of threads defined (--threads) time the amount of RAM defined (--memory)
// https://github.com/s-andrews/FastQC/blob/1faeea0412093224d7f6a07f777fad60a5650795/fastqc#L211-L222
// Dividing the task.memory by task.cpus allows to stick to requested amount of RAM in the label
def memory_in_mb = task.memory
    ? (task.memory.toUnit('MB') / task.cpus).intValue()
    : null
// FastQC memory value allowed range (100 - 10000)
def fastqc_memory = memory_in_mb > 10000 ? 10000 : (memory_in_mb < 100 ? 100 : memory_in_mb)
def fastqc_memory_arg = fastqc_memory ? "--memory ${fastqc_memory}" : ''

"""
printf "%s %s\\n" ${rename_to} | while read old_name new_name; do
    [ -f "\${new_name}" ] || ln -s \$old_name \$new_name
done

fastqc \\
    ${args} \\
    --threads ${task.cpus} \\
    ${fastqc_memory_arg} \\
    ${renamed_files}

def prefix = task.ext.prefix ?: "${meta.id}"
def readList = reads instanceof List ? reads.collect { it.toString() } : [reads.toString()]
if (meta.single_end) {
    if (readList.size >= 1) {
        """
        cat ${readList.join(' ')} > ${prefix}.merged.fastq.gz

        cat <<-END_VERSIONS > versions.yml
        "${task.process}":
            cat: \$(echo \$(cat --version 2>&1) | sed 's/^.*coreutils) //; s/ .*\$//')
        END_VERSIONS
        """
    } else {
        error("Could not find any FASTQ files to concatenate in the process input")
    }
}
else {
    if (readList.size >= 2) {
        def read1 = []
        def read2 = []
        readList.eachWithIndex { v, ix -> (ix & 1 ? read2 : read1) << v }
        """
        cat ${read1.join(' ')} > ${prefix}_1.merged.fastq.gz
        cat ${read2.join(' ')} > ${prefix}_2.merged.fastq.gz

        cat <<-END_VERSIONS > versions.yml
        "${task.process}":
            cat: \$(echo \$(cat --version 2>&1) | sed 's/^.*coreutils) //; s/ .*\$//')
        END_VERSIONS
        """
    } else {
        error("Could not find any FASTQ file pairs to concatenate in the process input")
    }
}

# Write one abundance file per read set in a single streaming pass. The depth
# file is never decompressed to disk: on shared/object-backed work dirs the
# plaintext copy and one full read per column are prohibitively slow.
gzip -cd ${depth} | bioawk -t '
    NR == 1 {
        n_abund = int((NF - 3) / 2)
        for (i = 1; i <= n_abund; i++) {
            name = \$(i * 2 + 2)
            sub(/\\.bam\$/, "", name)
            abund[i] = name ".abund"
        }
        next
    }
    {
        for (i = 1; i <= n_abund; i++) {
            print \$1, \$(i * 2 + 2) > (abund[i])
        }
    }
'

cat <<-END_VERSIONS > versions.yml
"${task.process}":
    bioawk: \$(bioawk --version | cut -f 3 -d ' ' )
END_VERSIONS
